const stages=[{name:'היערכות ורתימה',sub:'מניחים את התשתית',color:'#2457e5',goal:'קביעת שותפות בית־ספרית וביסוס נקודת ייחוס (Baseline).',tasks:['קיימנו שיחת היכרות ותיאום ציפיות עם הנהלת בית הספר','הבהרנו את מטרת התהליך ואת אופן העבודה המשותפת','זיהינו מראש אתגרים והזדמנויות אפשריים','מנהל/ת בית הספר והצוות מכירים את העיקרון הפדגוגי של התהליך','הגדרנו שגרות וסדירויות להמשך העבודה'],tip:'מה יעזור לצוות להרגיש שותף אמיתי בתהליך כבר מהמפגש הראשון?'},{name:'אבחון ומיפוי צרכים',sub:'מקשיבים לשטח',color:'#258dbb',goal:'הבנת נקודת המוצא וזיהוי הצרכים המרכזיים של בית הספר.',tasks:['אספנו נתונים ותמונת מצב קיימת','קיימנו שיחות עם הצוות החינוכי','זיהינו חוזקות ומשאבים זמינים','מיפינו את צורכי הלמידה המרכזיים','בחרנו אתגר מרכזי להתמקדות'],tip:'אילו קולות עדיין חסרים בתמונת המצב שאספנו?'},{name:'תכנון הלמידה',sub:'מתרגמים תובנות לתוכנית',color:'#24948e',goal:'בניית תוכנית למידה ממוקדת, עם יעדים ומדדי הצלחה.',tasks:['ניסחנו יעד ברור ומוסכם','הגדרנו מדדי הצלחה','בנינו רצף למידה ולוח זמנים','חילקנו אחריות בין השותפים','שיתפנו את התוכנית וקיבלנו משוב'],tip:'איך נדע שהלמידה יצרה שינוי שניתן לראות בשטח?'},{name:'יישום וליווי',sub:'הופכים תכנון לעשייה',color:'#55a17d',goal:'התנסות בשטח, ליווי מתמשך ושיפור מתוך הלמידה.',tasks:['יצאנו להתנסות ראשונה','תיעדנו את תהליך היישום','קיימנו מפגש ליווי ורפלקציה','אספנו משוב מהשותפים','עדכנו את התוכנית בהתאם לתובנות'],tip:'מה למדנו מההתנסות האחרונה, ומה נרצה לשנות בפעם הבאה?'},{name:'חילוץ המודל והטמעה',sub:'מצמיחים השפעה לאורך זמן',color:'#879c4b',goal:'איסוף הידע שנוצר ובניית תשתית להמשכיות ולהרחבה.',tasks:['סיכמנו תובנות מרכזיות מהתהליך','בחַנו התקדמות ביחס למדדים','תיעדנו פרקטיקות מוצלחות','שיתפנו את הידע עם הצוות','בנינו תוכנית להמשך ולהטמעה'],tip:'מה חשוב לשמר כדי שהשינוי ימשיך גם לאחר סיום הליווי?'}];
let data={stage:0,checks:stages.map(()=>[]),fields:{},schools:[{}]};try{const saved=JSON.parse(localStorage.getItem('pilot67-v1'));if(saved&&Array.isArray(saved.checks)&&Array.isArray(saved.schools))data={...data,...saved}}catch{}let view='journey';const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('pilot67-v1',JSON.stringify(data));$('saveState').textContent='✓ כל השינויים נשמרו במכשיר זה'}catch{$('saveState').textContent='לא ניתן לשמור בדפדפן — מומלץ לייצא גיבוי'}update()}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
function update(){const done=data.checks.reduce((a,b)=>a+b.filter(Boolean).length,0);$('total').textContent=Math.round(done/25*100)+'%';$('bar').style.width=done/25*100+'%';$('taskCount').textContent=done;$('schoolCount').textContent=data.schools.length;$('steps').innerHTML=stages.map((s,i)=>`<button class="step ${i===data.stage&&view==='journey'?'active':''}" style="--accent:${s.color}" data-stage="${i}"><div class="stepHead"><span class="num">${i+1}</span><span class="stepStatus ${data.checks[i].filter(Boolean).length===5?'statusComplete':data.checks[i].some(Boolean)?'statusProgress':'statusWaiting'}">${data.checks[i].filter(Boolean).length===5?'הושלם ✓':data.checks[i].some(Boolean)?'בתהליך':'ממתין להתחלה'}</span></div><strong>${s.name}</strong><small>${s.sub}</small></button>`).join('');$('tip').textContent=stages[data.stage].tip}
function field(label,key,type='text',scope='fields',index=0){const value=scope==='schools'?data.schools[index][key]:data.fields[key];return `<label class="field ${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea data-key="${key}" data-scope="${scope}" data-index="${index}" placeholder="כתבו כאן…">${esc(value)}</textarea>`:`<input type="${type}" data-key="${key}" data-scope="${scope}" data-index="${index}" value="${esc(value)}" placeholder="${label}" ${type==='email'||type==='tel'?'dir="ltr"':''}>`}</label>`}
function schools(){return data.schools.map((s,i)=>`<div class="school"><div class="schoolHead"><b><span style="color:#2457e5">${String(i+1).padStart(2,'0')} / </span> ${esc(s.name||'בית ספר '+(i+1))}</b>${data.schools.length>1?`<button data-remove="${i}">הסרת בית ספר</button>`:''}</div><div class="fields">${field('שם בית הספר','name','text','schools',i)}${field('סמל מוסד','code','text','schools',i)}${field('שלב חינוך','level','text','schools',i)}${field('האתגר המרכזי של בית הספר','challenge','textarea','schools',i)}${field('יעדים ותוצאות רצויות','goals','textarea','schools',i)}</div></div>`).join('')+'<button class="add" id="addSchool">＋ הוספת בית ספר</button>'}
function render(){update();const s=stages[data.stage];$('content').innerHTML=view==='schools'?`<div class="sectionTop"><div><p class="eyebrow">השותפים לדרך</p><h2>בתי הספר שלי</h2><p>פרטי בתי הספר, האתגרים והיעדים המשותפים.</p></div></div>${schools()}`:`<div class="sectionTop"><div><span class="stageTag">שלב ${data.stage+1} מתוך 5</span><h2>${s.name}</h2><p>${s.sub} · מסע הלמידה הבית־ספרי</p></div><span style="color:#b3c4ef;font-size:34px">${['⚑','◎','◇','↗','✧'][data.stage]}</span></div><div class="target"><span class="targetIcon">◎</span><div><small>מטרת השלב</small><p>${s.goal}</p></div></div><div class="sectionLabel"><h3>מה כבר עשינו בתהליך?</h3><span>${data.checks[data.stage].filter(Boolean).length} מתוך 5 הושלמו</span></div>${s.tasks.map((t,i)=>`<label class="check"><input type="checkbox" data-task="${i}" ${data.checks[data.stage][i]?'checked':''}><span>${t}</span></label>`).join('')}<hr class="divider">${data.stage===0?`<h3>פרטי המוביל/ה ופרטי בית הספר</h3><div class="fields">${field('שם המוביל/ה','contact')}${field('כתובת דוא״ל','email','email')}${field('טלפון','phone','tel')}</div>${field('הערות ותיאום ציפיות','intro','textarea')}${schools()}`:`<h3>מתעדים את הדרך</h3>${field('תובנות מרכזיות','notes'+data.stage,'textarea')}${field('הצעדים הבאים','next'+data.stage,'textarea')}<div class="fields">${field('אחראי/ת לביצוע','owner'+data.stage)}${field('תאריך למפגש הבא','date'+data.stage,'date')}</div>`}<div class="actions"><button id="prev" ${data.stage===0?'disabled':''}>→ לשלב הקודם</button><button class="primary" id="next">${data.stage===4?'סיכום התהליך ✓':'לשלב הבא ←'}</button></div>`}
document.addEventListener('click',e=>{const stage=e.target.closest('[data-stage]');if(stage){data.stage=+stage.dataset.stage;view='journey';setNav();save();render()}if(e.target.closest('#addSchool')){data.schools.push({});save();render()}const remove=e.target.closest('[data-remove]');if(remove){if(confirm('להסיר את בית הספר ואת הנתונים שהוזנו עבורו?')){data.schools.splice(+remove.dataset.remove,1);save();render()}}if(e.target.closest('#next')){if(data.stage<4){data.stage++;save();render();$('content').scrollIntoView({behavior:'smooth',block:'start'})}else toast('השלמתם '+data.checks.flat().filter(Boolean).length+' מתוך 25 משימות במסע')}if(e.target.closest('#prev')&&data.stage>0){data.stage--;save();render()}const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;setNav();render()}});
function setNav(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.key){if(t.dataset.scope==='schools')data.schools[+t.dataset.index][t.dataset.key]=t.value;else data.fields[t.dataset.key]=t.value;save()}});document.addEventListener('change',e=>{if(e.target.dataset.task!==undefined){data.checks[data.stage][+e.target.dataset.task]=e.target.checked;save();const label=document.querySelector('.sectionLabel>span');if(label)label.textContent=data.checks[data.stage].filter(Boolean).length+' מתוך 5 הושלמו'}});
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='pilot67-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url);toast('קובץ הגיבוי יוצא בהצלחה')};$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const d=JSON.parse(await f.text());if(!Array.isArray(d.checks)||d.checks.length!==5||!d.checks.every(c=>Array.isArray(c)&&c.length<=5&&c.every(v=>typeof v==='boolean'))||!Array.isArray(d.schools)||!d.schools.every(s=>s&&typeof s==='object')||!d.fields||typeof d.fields!=='object'||!Number.isInteger(d.stage)||d.stage<0||d.stage>4)throw Error();if(confirm('טעינת הגיבוי תחליף את הנתונים במכשיר זה. להמשיך?')){data=d;save();render();toast('הגיבוי נטען בהצלחה')}}catch{toast('הקובץ אינו גיבוי תקין של פיילוט 67')}e.target.value=''};render();

